Winform程序中光标在TextBox控件中时按下 Ctrl + A 快捷键，并不能选中全部文字，而是会发出警告音。本文给出实现方法。

在TextBox控件中使用快捷键，一般要求按下快捷键立刻产生效果，KeyUp事件显然不符合我们的要求，而KeyPress事件中不支持使用组合件，所以我们选用KeyDown事件，具体代码实现如下：
private void tBBefore_KeyDown(object sender, KeyEventArgs e)&#123;    if (e.Control &amp;&amp; e.KeyCode == Keys.A)    &#123;        ((TextBox)sender).SelectAll();    &#125;&#125;

质数是指在大于1的自然数中，除了1和它本身以外不再有其他因数的数。本文列举了几种求区间内所有质数的算法。

一般方法验证质数我们根据质数的定义可以对某一自然数进行检测，方法如下：
/// &lt;summary&gt;/// 判断自然数是否是质数/// &lt;/summary&gt;/// &lt;param name=&quot;n&quot;&gt;需要判断的数&lt;/param&gt;/// &lt;returns&gt;是/否&lt;/returns&gt;public static bool IsPrime(int n)&#123;    if (n &lt; 2) return false;    for (var i = n - 1; i &gt; 1; i--)    &#123;        //n除以每个比n小比1大的自然数        if (n % i == 0)            //如果有能被整除的，则不是质数            return false;    &#125;    //否则则为质数    return true;&#125;
获取范围内质数/// &lt;summary&gt;/// 获取自然数区间内的所有质数/// &lt;/summary&gt;/// &lt;param name=&quot;startInt&quot;&gt;自然数区间起始点&lt;/param&gt;/// &lt;param name=&quot;endInt&quot;&gt;自然数区间终点&lt;/param&gt;/// &lt;returns&gt;自然数区间内的所有质数的集合&lt;/returns&gt;public static IEnumerable&lt;int&gt; GetPrimes(int startInt, int endInt)&#123;    for (var i = startInt; i &lt;= endInt; i++)        if (IsPrime(i))            yield return i;&#125;
筛法什么是筛法科普篇:筛法是一种简单检定质数的算法。据说是古希腊的埃拉托斯特尼（Eratosthenes）发明的，又称埃拉托斯特尼筛法（sieve of Eratosthenes）.
使用筛法求某上限内所有质数/// &lt;summary&gt;/// 求某上限内的所有质数/// &lt;/summary&gt;/// &lt;param name=&quot;j&quot;&gt;上限自然数&lt;/param&gt;/// &lt;returns&gt;上限内所有质数&lt;/returns&gt;public static IEnumerable&lt;int&gt; GenPrime(int j)&#123;    var bts = new BitArray(j + 1);    for (var x = 2; x &lt; bts.Length / 2; x++)        for (var y = x + 1; y &lt; bts.Length; y++)            if (bts[y] == false &amp;&amp; y % x == 0)                bts[y] = true;    for (var x = 2; x &lt; bts.Length; x++)        if (bts[x] == false)            yield return x;&#125;
使用筛法求某自然数区间内所有质数使用两次上面的方法分别求取区间起始点和终点作为上限的所有质数后取差集
/// &lt;summary&gt;/// 获取自然数区间内的所有质数/// &lt;/summary&gt;/// &lt;param name=&quot;startInt&quot;&gt;自然数区间起始点&lt;/param&gt;/// &lt;param name=&quot;endInt&quot;&gt;自然数区间终点&lt;/param&gt;/// &lt;returns&gt;自然数区间内的所有质数的集合&lt;/returns&gt;public static IEnumerable&lt;int&gt; GenPrimes(int startInt, int endInt) =&gt;     GenPrime(endInt).Except(GenPrime(startInt));
快速线性筛法实现在某位高手的博文中发现了复杂度更低的线性筛法

一般筛法求素数+快速线性筛法求素数

下面是C#的实现
/// &lt;summary&gt;/// 求某上限内的所有质数/// &lt;/summary&gt;/// &lt;param name=&quot;x&quot;&gt;上限自然数&lt;/param&gt;/// &lt;returns&gt;上限内所有质数&lt;/returns&gt;private static IEnumerable&lt;int&gt; LinearGenPrime(int x)&#123;    var numPrime = 0;    var ints = new List&lt;int&gt;();    var isNotPrime = new BitArray(x);    for (var i = 2; i &lt; x; i++)    &#123;        if (!isNotPrime[i])        &#123;            yield return i;            numPrime++;        &#125;        for (var j = 0; j &lt; numPrime &amp;&amp; i * ints[j] &lt; x; j++)        &#123;            isNotPrime[i * ints[j]] = true;            if (!Convert.ToBoolean(i % ints[j]))                break;        &#125;    &#125;&#125;

话不多说，直接上代码，类库中的机器码使用序列号、硬盘ID、网卡MAC地址组合取MD5生成。

using System;using System.Linq;using System.Management;using System.Security.Cryptography;using System.Text;namespace WayneShao.Common&#123;    internal static class MachineCode    &#123;        private static string _machineCodeString;        public static string Value        &#123;            get            &#123;                if (string.IsNullOrWhiteSpace(_machineCodeString))                    _machineCodeString = GetMD5($&quot;&#123;CPUCode&#125;_&#123;HDId&#125;_&#123;MacAddress&#125;&quot;);                return _machineCodeString;            &#125;        &#125;        private static string _cpuCode;        public static string CPUCode =&gt; _cpuCode ?? (_cpuCode = GetCPUInfo());        private static string _hdId;        public static string HDId =&gt; _hdId ?? (_hdId = GetHDid());        private static string _macAddress;        public static string MacAddress =&gt; _macAddress ?? (_macAddress = GetMACAddress());        ///   &lt;summary&gt;         ///   获取cpu序列号             ///   &lt;/summary&gt;         ///   &lt;returns&gt; string &lt;/returns&gt;         private static string GetCPUInfo()        &#123;            using (var cimobject = new ManagementClass(&quot;Win32_Processor&quot;))            &#123;                var hdids = cimobject.GetInstances().Cast&lt;ManagementObject&gt;().Select(o =&gt; o.Properties[&quot;ProcessorId&quot;].Value).Cast&lt;string&gt;().ToArray();                return hdids.Any() ? hdids.First() : string.Empty;            &#125;        &#125;        ///   &lt;summary&gt;         ///   获取硬盘ID             ///   &lt;/summary&gt;         ///   &lt;returns&gt; string &lt;/returns&gt;         private static string GetHDid()        &#123;            using (var cimobject1 = new ManagementClass(&quot;Win32_DiskDrive&quot;))            &#123;                var hdids = cimobject1.GetInstances().Cast&lt;ManagementObject&gt;().Select(o =&gt; o.Properties[&quot;Model&quot;].Value).Cast&lt;string&gt;().ToArray();                return hdids.Any() ? hdids.First() : string.Empty;            &#125;        &#125;        ///   &lt;summary&gt;         ///   获取网卡硬件地址         ///   &lt;/summary&gt;         ///   &lt;returns&gt; string &lt;/returns&gt;         private static string GetMACAddress()        &#123;            using (var mc = new ManagementClass(&quot;Win32_NetworkAdapterConfiguration&quot;))            &#123;                var macs = mc.GetInstances().Cast&lt;ManagementObject&gt;().Where(o =&gt; (bool)o[&quot;IPEnabled&quot;]).Select(o =&gt; o[&quot;MacAddress&quot;].ToString()).ToArray();                return macs.Any() ? macs.First() : string.Empty;            &#125;        &#125;        ///   &lt;summary&gt;         ///   获取字符串的MD5值        ///   &lt;/summary&gt;         ///   &lt;returns&gt; string &lt;/returns&gt;         public static string GetMD5(string source)        &#123;            var result = Encoding.Default.GetBytes(source);            var md5 = new MD5CryptoServiceProvider();            var output = md5.ComputeHash(result);            return BitConverter.ToString(output).Replace(&quot;-&quot;, &quot;&quot;).ToLower();        &#125;    &#125;&#125;
