在Web应用运行过程中，我们难免会遇到程序运行异常，这个时候我们就应该将异常信息记录下来，以便开发人员和维护人员对异常原因进行还原，对异常原因进行修复。在ASP.NET平台中进行日志记录的组件也有很多，如Log4Net、CommonLogging等，我们这里选用Log4Net进行异常日志的记录。

捕获异常在ASP.NET MVC中提供了一个全局的异常处理过滤器：HandleErrorAttribute，可以通过该过滤器捕获异常信息。
我们在Models文件夹下新建类型Log4ExceptionAttribute，继承HandleErrorAttribute类，同时重写OnException方法来捕获异常数据：      
using System.Web.Mvc;namespace PMS.WebApp.Models&#123;    public class Log4ExceptionAttribute:HandleErrorAttribute    &#123;        /// &lt;summary&gt;        /// 重写OnException方法来捕获异常数据        /// &lt;/summary&gt;        /// &lt;param name=&quot;filterContext&quot;&gt;&lt;/param&gt;        public override void OnException(ExceptionContext filterContext)        &#123;            base.OnException(filterContext);            //捕获当前异常数据            var ex = filterContext.Exception;        &#125;    &#125;&#125;
新建过滤器后我们还需要在Global文件中调用的RegisterGlobalFilters方法中完成自己定义异常处理过滤的注册。
using System.Web.Mvc;using PMS.WebApp.Models;namespace PMS.WebApp&#123;    public class FilterConfig    &#123;        public static void RegisterGlobalFilters(GlobalFilterCollection filters)        &#123;            //filters.Add(new HandleErrorAttribute());            filters.Add(new Log4ExceptionAttribute());        &#125;    &#125;&#125;
队列处理考虑到多用户并发操作时可能产生的问题，我们需要新建一个队列来进行异常信息的暂存，同时开辟一个线程专门对队列中的异常信息进行处理。
在Log4ExceptionAttribute类中新建一个静态的异常类型的队列，在发生异常后，程序自动触发OnException方法，方法中将当前的异常信息入队后，跳转到错误页面。
using System;using System.Collections.Generic;using System.Web.Mvc;namespace PMS.WebApp.Models&#123;    public class Log4ExceptionAttribute:HandleErrorAttribute    &#123;        public static Queue&lt;Exception&gt; Exceptions=new Queue&lt;Exception&gt;();        /// &lt;summary&gt;        /// 重写OnException方法来捕获异常数据        /// &lt;/summary&gt;        /// &lt;param name=&quot;filterContext&quot;&gt;&lt;/param&gt;        public override void OnException(ExceptionContext filterContext)        &#123;            base.OnException(filterContext);            //捕获当前异常数据            var ex = filterContext.Exception;            //将异常数据入队            Exceptions.Enqueue(ex);            //跳转到错误页面            filterContext.HttpContext.Response.Redirect(&quot;/Error.html&quot;);        &#125;    &#125;&#125;
Log4Net的配置是在应用程序配置文件中进行的，我们先在配置文件中进行Log4Net的配置。Log4Net需要配置的节点位置和SpringNet完全相同，首先需要在configSessions中新增子节点,然后在configuration节点中增加log4net节点完成具体配置。
&lt;configuration&gt;  &lt;configSections&gt;    &lt;section name=&quot;entityFramework&quot; type=&quot;System.Data.Entity.Internal.ConfigFile.EntityFrameworkSection, EntityFramework, Version=6.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot; requirePermission=&quot;false&quot; /&gt;    &lt;!-- For more information on Entity Framework configuration, visit http://go.microsoft.com/fwlink/?LinkID=237468 --&gt;        &lt;!--↓Log4Net配置↓--&gt;    &lt;section name=&quot;log4net&quot; type=&quot;log4net.Config.Log4NetConfigurationSectionHandler, log4net&quot;/&gt;    &lt;!--↑Log4Net配置↑--&gt;        &lt;!--↓Spring.Net配置↓--&gt;    &lt;sectionGroup name=&quot;spring&quot;&gt;      &lt;section name=&quot;context&quot; type=&quot;Spring.Context.Support.MvcContextHandler, Spring.Web.Mvc4&quot;/&gt;    &lt;/sectionGroup&gt;    &lt;!--↑Spring.Net配置↑--&gt;      &lt;/configSections&gt;    &lt;!--↓Spring.Net配置↓--&gt;  &lt;spring&gt;    &lt;context&gt;      &lt;resource uri=&quot;file://~/Config/controllers.xml&quot;/&gt;      &lt;resource uri=&quot;file://~/Config/services.xml&quot;/&gt;    &lt;/context&gt;  &lt;/spring&gt;  &lt;!--↑Spring.Net配置↑--&gt;    &lt;!--↓Log4Net配置↓--&gt;  &lt;log4net&gt;    &lt;!-- OFF, FATAL, ERROR, WARN, INFO, DEBUG, ALL --&gt;    &lt;!-- Set root logger level to ERROR and its appenders --&gt;    &lt;root&gt;      &lt;level value=&quot;ALL&quot;/&gt;      &lt;appender-ref ref=&quot;SysAppender&quot;/&gt;    &lt;/root&gt;    &lt;!-- Print only messages of level DEBUG or above in the packages --&gt;    &lt;logger name=&quot;WebLogger&quot;&gt;      &lt;level value=&quot;DEBUG&quot;/&gt;    &lt;/logger&gt;    &lt;appender name=&quot;SysAppender&quot; type=&quot;log4net.Appender.RollingFileAppender,log4net&quot; &gt;      &lt;param name=&quot;File&quot; value=&quot;App_Data/&quot; /&gt;      &lt;param name=&quot;AppendToFile&quot; value=&quot;true&quot; /&gt;      &lt;param name=&quot;RollingStyle&quot; value=&quot;Date&quot; /&gt;      &lt;param name=&quot;DatePattern&quot; value=&quot;&amp;quot;Logs_&amp;quot;yyyyMMdd&amp;quot;.txt&amp;quot;&quot; /&gt;      &lt;param name=&quot;StaticLogFileName&quot; value=&quot;false&quot; /&gt;      &lt;layout type=&quot;log4net.Layout.PatternLayout,log4net&quot;&gt;        &lt;param name=&quot;ConversionPattern&quot; value=&quot;%d [%t] %-5p %c - %m%n&quot; /&gt;        &lt;param name=&quot;Header&quot; value=&quot;&amp;#13;&amp;#10;----------------------header--------------------------&amp;#13;&amp;#10;&quot; /&gt;        &lt;param name=&quot;Footer&quot; value=&quot;&amp;#13;&amp;#10;----------------------footer--------------------------&amp;#13;&amp;#10;&quot; /&gt;      &lt;/layout&gt;    &lt;/appender&gt;    &lt;appender name=&quot;consoleApp&quot; type=&quot;log4net.Appender.ConsoleAppender,log4net&quot;&gt;      &lt;layout type=&quot;log4net.Layout.PatternLayout,log4net&quot;&gt;        &lt;param name=&quot;ConversionPattern&quot; value=&quot;%d [%t] %-5p %c - %m%n&quot; /&gt;      &lt;/layout&gt;    &lt;/appender&gt;  &lt;/log4net&gt;  &lt;!--↑Log4Net配置↑--&gt;  ...&lt;/configuration&gt;
进阶配置在配置文件中可以对日志记录的信息、格式、文件名等作出具体的配置，下面是配置信息的详解
&lt;?xml version=&quot;1.0&quot;?&gt;&lt;configuration&gt;  &lt;configSections&gt;    &lt;section name=&quot;log4net&quot;              type=&quot;log4net.Config.Log4NetConfigurationSectionHandler,log4net&quot;/&gt;  &lt;/configSections&gt;  &lt;!--站点日志配置部分--&gt;  &lt;log4net&gt;    &lt;root&gt;      &lt;!--控制级别，由低到高: ALL|DEBUG|INFO|WARN|ERROR|FATAL|OFF--&gt;      &lt;!--比如定义级别为INFO，则INFO级别向下的级别，比如DEBUG日志将不会被记录--&gt;      &lt;!--如果没有定义LEVEL的值，则缺省为DEBUG--&gt;      &lt;level value=&quot;ERROR&quot;/&gt;      &lt;appender-ref ref=&quot;RollingFileAppender&quot;/&gt;    &lt;/root&gt;    &lt;appender name=&quot;RollingFileAppender&quot; type=&quot;log4net.Appender.RollingFileAppender&quot;&gt;      &lt;!--日志文件名开头--&gt;      &lt;file value=&quot;c:\Log\TestLog4net.TXT&quot;/&gt;      &lt;!--多线程时采用最小锁定--&gt;      &lt;lockingModel type=&quot;log4net.Appender.FileAppender+MinimalLock&quot;/&gt;      &lt;!--日期的格式，每天换一个文件记录，如不设置则永远只记录一天的日志，需设置--&gt;      &lt;datePattern value=&quot;(yyyyMMdd)&quot;/&gt;      &lt;!--是否追加到文件,默认为true，通常无需设置--&gt;      &lt;appendToFile value=&quot;true&quot;/&gt;      &lt;!--变换的形式为日期，这种情况下每天只有一个日志--&gt;      &lt;!--此时MaxSizeRollBackups和maximumFileSize的节点设置没有意义--&gt;      &lt;!--&lt;rollingStyle value=&quot;Date&quot;/&gt;--&gt;      &lt;!--变换的形式为日志大小--&gt;      &lt;!--这种情况下MaxSizeRollBackups和maximumFileSize的节点设置才有意义--&gt;      &lt;RollingStyle value=&quot;Size&quot;/&gt;      &lt;!--每天记录的日志文件个数，与maximumFileSize配合使用--&gt;      &lt;MaxSizeRollBackups value=&quot;10&quot;/&gt;      &lt;!--每个日志文件的最大大小--&gt;      &lt;!--可用的单位:KB|MB|GB--&gt;      &lt;!--不要使用小数,否则会一直写入当前日志--&gt;      &lt;maximumFileSize value=&quot;2MB&quot;/&gt;      &lt;!--日志格式--&gt;      &lt;layout type=&quot;log4net.Layout.PatternLayout&quot;&gt;        &lt;conversionPattern value=&quot;%date [%t]%-5p %c - %m%n&quot;/&gt;      &lt;/layout&gt;    &lt;/appender&gt;  &lt;/log4net&gt;&lt;/configuration&gt;
在Global文件中的Application_Start方法中开启一个线程，用于将队列中的错误信息写入日志文件。
using System.Linq;using System.Threading;using System.Web.Http;using System.Web.Mvc;using System.Web.Optimization;using System.Web.Routing;using log4net;using PMS.WebApp.Models;using Spring.Web.Mvc;namespace PMS.WebApp&#123;    // 注意: 有关启用 IIS6 或 IIS7 经典模式的说明，    // 请访问 http://go.microsoft.com/?LinkId=9394801    public class MvcApplication : SpringMvcApplication//HttpApplication    &#123;        protected void Application_Start()        &#123;            log4net.Config.XmlConfigurator.Configure();//读取Log4Net配置信息            AreaRegistration.RegisterAllAreas();            WebApiConfig.Register(GlobalConfiguration.Configuration);            FilterConfig.RegisterGlobalFilters(GlobalFilters.Filters);            RouteConfig.RegisterRoutes(RouteTable.Routes);            BundleConfig.RegisterBundles(BundleTable.Bundles);            //开启一个线程,扫描异常信息队列.            var filePath = Server.MapPath(&quot;/Log/&quot;);            ThreadPool.QueueUserWorkItem((a) =&gt;            &#123;                while (true)                &#123;                    //判断队列中是否有数据                    if (Log4ExceptionAttribute.Exceptions.Any())                    &#123;                        //出队一条异常信息                        var ex = Log4ExceptionAttribute.Exceptions.Dequeue();                        //若异常信息不为空                        if (ex == null) continue;                        //将异常信息写入到日志文件中                        var logger = LogManager.GetLogger(&quot;errorMsg&quot;);                        logger.Error(ex.ToString());                    &#125;                    else                    &#123;                        //若异常信息队列为空，则线程休息三秒                        Thread.Sleep(3000);                    &#125;                &#125;            &#125;, filePath);        &#125;    &#125;&#125;
成功完成错误日志的配置。

在之前的项目中，如果有需要使用验证码，基本都是自己用GDI+画图出来，简单好用，但是却也存在了一些小问题，首先若较少干扰线，则安全性不是很高，验证码容易被机器识别，若多画太多干扰线条，机器人识别率下降的同时，人眼的识别率也同步下降（震惊哭）。更为重要的是，GDI+绘制的验证码一般来说也不会很美观，如果做一个炫酷的登陆界面却配了这样一个验证码，画风诡异，丑到极致。
再后来浏览网页的过程中，发现很多很多网站项目中都使用了一种叫极验验证的验证码，采用移动滑块的方式进行验证，方便美观。而一番搜索之后了解到，官方提供的免费版也足以应付我手头的大多数项目了，不禁想把在MVC学习过程中试着使用极验验证来作为登录的验证码。

极验官方提供了C#的SDK和Demo供开发者参考，不过是Webform版本的，可读性不是很高，而现在使用Webform进行网站开发的也基本消失了，我将在官方Webform代码的基础上，将其用在ASP.NET MVC程序中。
注册极验到极验官网注册账号之后进入后台管理界面，点击添加验证添加后我们可以得到ID和KEY
完成验证逻辑首先我们需要引入官方的Geetestlib类using System;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Text;using System.Security.Cryptography;using System.Net;using System.IO;namespace PMS.WebApp.Models&#123;    /// &lt;summary&gt;    /// GeetestLib 极验验证C# SDK基本库    /// &lt;/summary&gt;    public class GeetestLib    &#123;        /// &lt;summary&gt;        /// SDK版本号        /// &lt;/summary&gt;        public const String version = &quot;3.2.0&quot;;        /// &lt;summary&gt;        /// SDK开发语言        /// &lt;/summary&gt;        public const String sdkLang = &quot;csharp&quot;;        /// &lt;summary&gt;        /// 极验验证API URL        /// &lt;/summary&gt;        protected const String apiUrl = &quot;http://api.geetest.com&quot;;        /// &lt;summary&gt;        /// register url        /// &lt;/summary&gt;        protected const String registerUrl = &quot;/register.php&quot;;        /// &lt;summary&gt;        /// validate url        /// &lt;/summary&gt;        protected const String validateUrl = &quot;/validate.php&quot;;        /// &lt;summary&gt;        /// 极验验证API服务状态Session Key        /// &lt;/summary&gt;        public const String gtServerStatusSessionKey = &quot;gt_server_status&quot;;        /// &lt;summary&gt;        /// 极验验证二次验证表单数据 Chllenge        /// &lt;/summary&gt;        public const String fnGeetestChallenge = &quot;geetest_challenge&quot;;        /// &lt;summary&gt;        /// 极验验证二次验证表单数据 Validate        /// &lt;/summary&gt;        public const String fnGeetestValidate = &quot;geetest_validate&quot;;        /// &lt;summary&gt;        /// 极验验证二次验证表单数据 Seccode        /// &lt;/summary&gt;        public const String fnGeetestSeccode = &quot;geetest_seccode&quot;;        private String userID = &quot;&quot;;        private String responseStr = &quot;&quot;;        private String captchaID = &quot;&quot;;        private String privateKey = &quot;&quot;;        /// &lt;summary&gt;        /// 验证成功结果字符串        /// &lt;/summary&gt;        public const int successResult = 1;        /// &lt;summary&gt;        /// 证结失败验果字符串        /// &lt;/summary&gt;        public const int failResult = 0;        /// &lt;summary&gt;        /// 判定为机器人结果字符串        /// &lt;/summary&gt;        public const String forbiddenResult = &quot;forbidden&quot;;        /// &lt;summary&gt;        /// GeetestLib构造函数        /// &lt;/summary&gt;        /// &lt;param name=&quot;publicKey&quot;&gt;极验验证公钥&lt;/param&gt;        /// &lt;param name=&quot;privateKey&quot;&gt;极验验证私钥&lt;/param&gt;        public GeetestLib(String publicKey, String privateKey)        &#123;            this.privateKey = privateKey;            this.captchaID = publicKey;        &#125;        private int getRandomNum()        &#123;            Random rand =new Random();            int randRes = rand.Next(100);            return randRes;        &#125;        /// &lt;summary&gt;        /// 验证初始化预处理        /// &lt;/summary&gt;        /// &lt;returns&gt;初始化结果&lt;/returns&gt;        public Byte preProcess()        &#123;            if (this.captchaID == null)            &#123;                Console.WriteLine(&quot;publicKey is null!&quot;);            &#125;            else            &#123;                String challenge = this.registerChallenge();                if (challenge.Length == 32)                &#123;                    this.getSuccessPreProcessRes(challenge);                    return 1;                &#125;                else                &#123;                    this.getFailPreProcessRes();                    Console.WriteLine(&quot;Server regist challenge failed!&quot;);                &#125;            &#125;            return 0;        &#125;        public Byte preProcess(String userID)        &#123;            if (this.captchaID == null)            &#123;                Console.WriteLine(&quot;publicKey is null!&quot;);            &#125;            else            &#123;                this.userID = userID;                String challenge = this.registerChallenge();                if (challenge.Length == 32)                &#123;                    this.getSuccessPreProcessRes(challenge);                    return 1;                &#125;                else                &#123;                    this.getFailPreProcessRes();                    Console.WriteLine(&quot;Server regist challenge failed!&quot;);                &#125;            &#125;            return 0;        &#125;        public String getResponseStr()        &#123;            return this.responseStr;        &#125;        /// &lt;summary&gt;        /// 预处理失败后的返回格式串        /// &lt;/summary&gt;        private void getFailPreProcessRes()        &#123;            int rand1 = this.getRandomNum();            int rand2 = this.getRandomNum();            String md5Str1 = this.md5Encode(rand1 + &quot;&quot;);            String md5Str2 = this.md5Encode(rand2 + &quot;&quot;);            String challenge = md5Str1 + md5Str2.Substring(0, 2);            this.responseStr = &quot;&#123;&quot; + string.Format(                 &quot;\&quot;success\&quot;:&#123;0&#125;,\&quot;gt\&quot;:\&quot;&#123;1&#125;\&quot;,\&quot;challenge\&quot;:\&quot;&#123;2&#125;\&quot;&quot;, 0,                this.captchaID, challenge) + &quot;&#125;&quot;;        &#125;        /// &lt;summary&gt;        /// 预处理成功后的标准串        /// &lt;/summary&gt;        private void getSuccessPreProcessRes(String challenge)        &#123;            challenge = this.md5Encode(challenge + this.privateKey);            this.responseStr =&quot;&#123;&quot; + string.Format(                &quot;\&quot;success\&quot;:&#123;0&#125;,\&quot;gt\&quot;:\&quot;&#123;1&#125;\&quot;,\&quot;challenge\&quot;:\&quot;&#123;2&#125;\&quot;&quot;, 1,                 this.captchaID, challenge) + &quot;&#125;&quot;;        &#125;        /// &lt;summary&gt;        /// failback模式的验证方式        /// &lt;/summary&gt;        /// &lt;param name=&quot;challenge&quot;&gt;failback模式下用于与validate一起解码答案， 判断验证是否正确&lt;/param&gt;        /// &lt;param name=&quot;validate&quot;&gt;failback模式下用于与challenge一起解码答案， 判断验证是否正确&lt;/param&gt;        /// &lt;param name=&quot;seccode&quot;&gt;failback模式下，其实是个没用的参数&lt;/param&gt;        /// &lt;returns&gt;验证结果&lt;/returns&gt;        public int failbackValidateRequest(String challenge, String validate, String seccode)        &#123;            if (!this.requestIsLegal(challenge, validate, seccode)) return GeetestLib.failResult;            String[] validateStr = validate.Split(&#x27;_&#x27;);            String encodeAns = validateStr[0];            String encodeFullBgImgIndex = validateStr[1];            String encodeImgGrpIndex = validateStr[2];            int decodeAns = this.decodeResponse(challenge, encodeAns);            int decodeFullBgImgIndex = this.decodeResponse(challenge, encodeFullBgImgIndex);            int decodeImgGrpIndex = this.decodeResponse(challenge, encodeImgGrpIndex);            int validateResult = this.validateFailImage(decodeAns, decodeFullBgImgIndex, decodeImgGrpIndex);            return validateResult;        &#125;        private int validateFailImage(int ans, int full_bg_index, int img_grp_index)        &#123;            const int thread = 3;            String full_bg_name = this.md5Encode(full_bg_index + &quot;&quot;).Substring(0, 10);            String bg_name = md5Encode(img_grp_index + &quot;&quot;).Substring(10, 10);            String answer_decode = &quot;&quot;;            for (int i = 0;i &lt; 9; i++)            &#123;                if (i % 2 == 0) answer_decode += full_bg_name.ElementAt(i);                else if (i % 2 == 1) answer_decode += bg_name.ElementAt(i);            &#125;            String x_decode = answer_decode.Substring(4);            int x_int = Convert.ToInt32(x_decode, 16);            int result = x_int % 200;            if (result &lt; 40) result = 40;            if (Math.Abs(ans - result) &lt; thread) return GeetestLib.successResult;            else return GeetestLib.failResult;        &#125;        private Boolean requestIsLegal(String challenge, String validate, String seccode)        &#123;            if (challenge.Equals(string.Empty) || validate.Equals(string.Empty) || seccode.Equals(string.Empty)) return false;            return true;        &#125;        /// &lt;summary&gt;        /// 向gt-server进行二次验证        /// &lt;/summary&gt;        /// &lt;param name=&quot;challenge&quot;&gt;本次验证会话的唯一标识&lt;/param&gt;        /// &lt;param name=&quot;validate&quot;&gt;拖动完成后server端返回的验证结果标识字符串&lt;/param&gt;        /// &lt;param name=&quot;seccode&quot;&gt;验证结果的校验码，如果gt-server返回的不与这个值相等则表明验证失败&lt;/param&gt;        /// &lt;returns&gt;二次验证结果&lt;/returns&gt;        public int enhencedValidateRequest(String challenge, String validate, String seccode)        &#123;            if (!this.requestIsLegal(challenge, validate, seccode)) return GeetestLib.failResult;            if (validate.Length &gt; 0 &amp;&amp; checkResultByPrivate(challenge, validate))            &#123;                String query = &quot;seccode=&quot; + seccode + &quot;&amp;sdk=csharp_&quot; + GeetestLib.version;                String response = &quot;&quot;;                try                &#123;                    response = postValidate(query);                &#125;                catch (Exception e)                &#123;                    Console.WriteLine(e);                &#125;                if (response.Equals(md5Encode(seccode)))                &#123;                    return GeetestLib.successResult;                &#125;            &#125;            return GeetestLib.failResult;        &#125;        public int enhencedValidateRequest(String challenge, String validate, String seccode, String userID)        &#123;            if (!this.requestIsLegal(challenge, validate, seccode)) return GeetestLib.failResult;            if (validate.Length &gt; 0 &amp;&amp; checkResultByPrivate(challenge, validate))            &#123;                String query = &quot;seccode=&quot; + seccode + &quot;&amp;user_id=&quot; + userID + &quot;&amp;sdk=csharp_&quot; + GeetestLib.version;                String response = &quot;&quot;;                try                &#123;                    response = postValidate(query);                &#125;                catch (Exception e)                &#123;                    Console.WriteLine(e);                &#125;                if (response.Equals(md5Encode(seccode)))                &#123;                    return GeetestLib.successResult;                &#125;            &#125;            return GeetestLib.failResult;        &#125;        private String readContentFromGet(String url)        &#123;            try            &#123;                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);                request.Timeout = 20000;                HttpWebResponse response = (HttpWebResponse)request.GetResponse();                Stream myResponseStream = response.GetResponseStream();                StreamReader myStreamReader = new StreamReader(myResponseStream, Encoding.GetEncoding(&quot;utf-8&quot;));                String retString = myStreamReader.ReadToEnd();                myStreamReader.Close();                myResponseStream.Close();                return retString;            &#125;           catch           &#123;               return &quot;&quot;;                &#125;        &#125;        private String registerChallenge()        &#123;            String url = &quot;&quot;;            if (string.Empty.Equals(this.userID))            &#123;                url = string.Format(&quot;&#123;0&#125;&#123;1&#125;?gt=&#123;2&#125;&quot;, GeetestLib.apiUrl, GeetestLib.registerUrl, this.captchaID);            &#125;            else            &#123;                url = string.Format(&quot;&#123;0&#125;&#123;1&#125;?gt=&#123;2&#125;&amp;user_id=&#123;3&#125;&quot;, GeetestLib.apiUrl, GeetestLib.registerUrl, this.captchaID, this.userID);            &#125;            string retString = this.readContentFromGet(url);            return retString;        &#125;        private Boolean checkResultByPrivate(String origin, String validate)        &#123;            String encodeStr = md5Encode(privateKey + &quot;geetest&quot; + origin);            return validate.Equals(encodeStr);        &#125;        private String postValidate(String data)        &#123;            String url = string.Format(&quot;&#123;0&#125;&#123;1&#125;&quot;, GeetestLib.apiUrl, GeetestLib.validateUrl);            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);            request.Method = &quot;POST&quot;;            request.ContentType = &quot;application/x-www-form-urlencoded&quot;;            request.ContentLength = Encoding.UTF8.GetByteCount(data);            // 发送数据            Stream myRequestStream = request.GetRequestStream();            byte[] requestBytes = System.Text.Encoding.ASCII.GetBytes(data);            myRequestStream.Write(requestBytes, 0, requestBytes.Length);            myRequestStream.Close();            HttpWebResponse response = (HttpWebResponse)request.GetResponse();            // 读取返回信息            Stream myResponseStream = response.GetResponseStream();            StreamReader myStreamReader = new StreamReader(myResponseStream, Encoding.GetEncoding(&quot;utf-8&quot;));            string retString = myStreamReader.ReadToEnd();            myStreamReader.Close();            myResponseStream.Close();            return retString;        &#125;        private int decodeRandBase(String challenge)        &#123;            String baseStr = challenge.Substring(32, 2);            List&lt;int&gt; tempList = new List&lt;int&gt;();            for(int i = 0; i &lt; baseStr.Length; i++)            &#123;                int tempAscii = (int)baseStr[i];                tempList.Add((tempAscii &gt; 57) ? (tempAscii - 87)                    : (tempAscii - 48));            &#125;            int result = tempList.ElementAt(0) * 36 + tempList.ElementAt(1);            return result;        &#125;        private int decodeResponse(String challenge, String str)        &#123;            if (str.Length&gt;100) return 0;            int[] shuzi = new int[] &#123; 1, 2, 5, 10, 50&#125;;            String chongfu = &quot;&quot;;            Hashtable key = new Hashtable();            int count = 0;            for (int i=0;i&lt;challenge.Length;i++)            &#123;                String item = challenge.ElementAt(i) + &quot;&quot;;                if (chongfu.Contains(item)) continue;                else                &#123;                    int value = shuzi[count % 5];                    chongfu += item;                    count++;                    key.Add(item, value);                &#125;            &#125;            int res = 0;            for (int i = 0; i &lt; str.Length; i++) res += (int)key[str[i]+&quot;&quot;];            res = res - this.decodeRandBase(challenge);            return res;        &#125;        private String md5Encode(String plainText)        &#123;            MD5CryptoServiceProvider md5 = new MD5CryptoServiceProvider();            string t2 = BitConverter.ToString(md5.ComputeHash(UTF8Encoding.Default.GetBytes(plainText)));            t2 = t2.Replace(&quot;-&quot;, &quot;&quot;);            t2 = t2.ToLower();            return t2;        &#125;    &#125;&#125;
