最近在做爬虫的作业，今天学习的内容是关于DNS解析模块的制作的。使用的库为ARSoft.Tools.Net，它是一个非常强大的开源DNS控件库，包含.Net SPF validation, SenderID validation以及DNS Client、DNS Server接口。使用该接口可轻松实现DNS客户请求端及服务器解析端。

项目地址：http://arsofttoolsnet.codeplex.com/，
Nuget包地址：https://www.nuget.org/packages/ARSoft.Tools.Net/。
引入首先引入nuget包:

Install-Package ARSoft.Tools.NetInstall-Package ARSoft.Tools.Net

具体实现实现代码:/// &lt;summary&gt;/// DNS解析/// &lt;/summary&gt;/// &lt;param name=&quot;dnsServer&quot;&gt;DNS服务器IP&lt;/param&gt;/// &lt;param name=&quot;timeOut&quot;&gt;解析超时时间&lt;/param&gt;/// &lt;param name=&quot;url&quot;&gt;解析网址&lt;/param&gt;/// &lt;param name=&quot;isSuccess&quot;&gt;是否解析成功&lt;/param&gt;/// &lt;returns&gt;解析到的IP信息&lt;/returns&gt;public static IPAddress DnsResolver(string dnsServer, int timeOut, string url, out bool isSuccess)&#123;    //初始化DnsClient，第一个参数为DNS服务器的IP，第二个参数为超时时间    var dnsClient = new DnsClient(IPAddress.Parse(dnsServer), timeOut);    //解析域名。将域名请求发送至DNS服务器解析，第一个参数为需要解析的域名，第二个参数为    //解析类型， RecordType.A为IPV4类型    //DnsMessage dnsMessage = dnsClient.Resolve(&quot;www.sina.com&quot;, RecordType.A);    var s = new Stopwatch();    s.Start();    var dnsMessage = dnsClient.Resolve(DomainName.Parse(url));    s.Stop();    Console.WriteLine(s.Elapsed.Milliseconds);    //若返回结果为空，或者存在错误，则该请求失败。    if (dnsMessage == null || (dnsMessage.ReturnCode != ReturnCode.NoError &amp;&amp; dnsMessage.ReturnCode != ReturnCode.NxDomain))    &#123;        isSuccess= false;    &#125;    //循环遍历返回结果，将返回的IPV4记录添加到结果集List中。    if (dnsMessage != null)        foreach (var dnsRecord in dnsMessage.AnswerRecords)        &#123;            var aRecord = dnsRecord as ARecord;            if (aRecord == null) continue;            isSuccess = true;            return aRecord.Address;        &#125;    isSuccess= false;    return null;&#125;
调用代码bool isSuccess;IPAddress ip = DnsResolver(&quot;223.5.5.5&quot;, 200, &quot;shaoweicloud.cn&quot;, out isSuccess);if (isSuccess)    Console.WriteLine(ip);
进一步封装懂的使用方法后我们可以对它做进一步封装,得到DnsResolver类:
实现代码using System;using System.Collections.Generic;using System.Diagnostics;using System.Net;using ARSoft.Tools.Net;using ARSoft.Tools.Net.Dns;namespace Crawler.Protocol&#123;    public class DnsResolver    &#123;        public TimeSpan TimeSpan &#123; get; set; &#125;        public string Url &#123; get; set; &#125;        public List Record &#123; get; set; &#125;        public string DnsServer &#123; get; set; &#125;        public int TimeOut &#123; get; set; &#125;        public ReturnCode ReturnCode &#123; get; set; &#125;        public bool IsSuccess &#123; get; private set; &#125;        public DnsResolver(string url, string dnsServer = &quot;223.5.5.5&quot;, int timeOut = 200)        &#123;            Url = url;            DnsServer = dnsServer;            TimeOut = timeOut;            Record=new List();            Dig();        &#125;        public void Dig()        &#123;            //初始化DnsClient，第一个参数为DNS服务器的IP，第二个参数为超时时间            var dnsClient = new DnsClient(IPAddress.Parse(DnsServer), TimeOut);            var s = new Stopwatch();            s.Start();            //解析域名。将域名请求发送至DNS服务器解析，参数为需要解析的域名            var dnsMessage = dnsClient.Resolve(DomainName.Parse(Url));            s.Stop();            TimeSpan = s.Elapsed;            //若返回结果为空，或者存在错误，则该请求失败。            if (dnsMessage == null || (dnsMessage.ReturnCode != ReturnCode.NoError &amp;&amp; dnsMessage.ReturnCode != ReturnCode.NxDomain))                IsSuccess = false;            //循环遍历返回结果，将返回的IPV4记录添加到结果集List中。            if (dnsMessage != null)                foreach (var dnsRecord in dnsMessage.AnswerRecords)                &#123;                    var aRecord = dnsRecord as ARecord;                    if (aRecord == null) continue;                    IsSuccess = true;                    Record.Add(aRecord);                &#125;            if (dnsMessage != null) ReturnCode = dnsMessage.ReturnCode;        &#125;    &#125;&#125;
调用方法DnsResolver dns = new DnsResolver(&quot;shaoweicloud.cn&quot;);if (dns.IsSuccess)    Console.WriteLine(dns.Record[0]);

结束 至此，DNS解析模块就基本结束了，至于为什么标题中标注了半成品，是因为我想在基本的DNS解析功能的基础上根据解析到DNS信息中的TTL做一套信息缓存机制，减少不必要的重复查询，目前还在考虑使用何种方法，后续实现会更新。

为了便于使用及日后的扩展，将Scrapy简单封装为了Requester。

具体代码如下：
using System;using System.Collections.Generic;using Crawler.Common;namespace Crawler.Protocol&#123;    public class Requester    &#123;        private Uri Url &#123; get; set; &#125;        private Browser Browser &#123; get; set; &#125;        public Requester(string url, Dictionary&lt;string, string&gt; headers = null, Browser browser = null)        &#123;            var u = new Uri(url);            //检测地址是域名还是IP地址,如果是域名,则使用DnsResolver解析为IP地址            var leftPart = u.GetLeftPart(UriPartial.Authority).Replace(u.GetLeftPart(UriPartial.Scheme), &quot;&quot;);            //正则匹配是否为IP地址            if (!RegexHelper.IsMatch(leftPart, @&quot;\d+\.\d+\.\d+\.\d+\w&quot;))            &#123;                var dns = new DnsResolver(leftPart);                if (dns.IsSuccess)                    u = new Uri(url.Replace(leftPart, dns.Record.Address.ToString()));            &#125;            Url = u;            Browser = browser ?? new Browser();            if (headers == null) return;            foreach (var header in headers)                Browser.Headers[header.Key] = header.Value;        &#125;        public string GetHtml()        &#123;            return Browser.DownloadString(Url);        &#125;        public byte[] GetFile()        &#123;            return Browser.NavigateToPage(Url).RawResponse.Body;        &#125;    &#125;&#125;
