昨日在新生命团队钉钉群中，看到大石头老师分享了他们实现的 IndexOf 算法，据说可以做到 O(1)，第一反应是几乎不可能，了解之后得知是使用了 Boyer Moore 字符串搜索算法，据说这种算法常用于 IDE 工具的查找，比 KMP 更快，所以有了对各种常用字符串查找算法做一下 Benchmark 的想法。

横向对比的各个字符串查找算法string.IndexOf此方法为 FLC 中实现的 string 类型的方法，以下源码均已开源在 GitHub 。
// Determines the position within this string of the first occurence of the specified// string, according to the specified search criteria.  The search begins at// the first character of this string, it is case-sensitive and ordinal (code-point)// comparison is used.//[Pure]public int IndexOf(String value) &#123;    return IndexOf(value, StringComparison.CurrentCulture);&#125;
可以看到，默认使用了 StringComprison.CurrentCulture，关于其具体的定义，可以参照官方文档：通常情况我们使用 CurrentCulture 或是 Ordinal 都能很好的满足需求。

继续向下看（源码为节选，省略了无关内容）
[Pure]public int IndexOf(String value, StringComparison comparisonType) &#123;    return IndexOf(value, 0, this.Length, comparisonType);&#125;[Pure][System.Security.SecuritySafeCritical]public int IndexOf(String value, int startIndex, int count, StringComparison comparisonType) &#123;    // Validate inputs    if (value == null)        throw new ArgumentNullException(&quot;value&quot;);    if (startIndex &lt; 0 || startIndex &gt; this.Length)        throw new ArgumentOutOfRangeException(&quot;startIndex&quot;, Environment.GetResourceString(&quot;ArgumentOutOfRange_Index&quot;));    if (count &lt; 0 || startIndex &gt; this.Length - count)        throw new ArgumentOutOfRangeException(&quot;count&quot;, Environment.GetResourceString(&quot;ArgumentOutOfRange_Count&quot;));    Contract.EndContractBlock();    switch (comparisonType) &#123;        case StringComparison.CurrentCulture:            return CultureInfo.CurrentCulture.CompareInfo.IndexOf(this, value, startIndex, count, CompareOptions.None);        case StringComparison.CurrentCultureIgnoreCase:            return CultureInfo.CurrentCulture.CompareInfo.IndexOf(this, value, startIndex, count, CompareOptions.IgnoreCase);        case StringComparison.InvariantCulture:            return CultureInfo.InvariantCulture.CompareInfo.IndexOf(this, value, startIndex, count, CompareOptions.None);        case StringComparison.InvariantCultureIgnoreCase:            return CultureInfo.InvariantCulture.CompareInfo.IndexOf(this, value, startIndex, count, CompareOptions.IgnoreCase);        case StringComparison.Ordinal:            return CultureInfo.InvariantCulture.CompareInfo.IndexOf(this, value, startIndex, count, CompareOptions.Ordinal);        case StringComparison.OrdinalIgnoreCase:            if (value.IsAscii() &amp;&amp; this.IsAscii())                return CultureInfo.InvariantCulture.CompareInfo.IndexOf(this, value, startIndex, count, CompareOptions.IgnoreCase);            else                return TextInfo.IndexOfStringOrdinalIgnoreCase(this, value, startIndex, count);        default:            throw new ArgumentException(Environment.GetResourceString(&quot;NotSupported_StringComparison&quot;), &quot;comparisonType&quot;);    &#125;  &#125;

下面继续跟着源码来到 CompareInfo
public unsafe virtual int IndexOf(String source, char value, CompareOptions options)&#123;    if (source==null)        throw new ArgumentNullException(&quot;source&quot;);    Contract.EndContractBlock();    return IndexOf(source, value, 0, source.Length, options);&#125;[System.Security.SecuritySafeCritical]  // auto-generated[ResourceExposure(ResourceScope.None)][ResourceConsumption(ResourceScope.Process, ResourceScope.Process)]public unsafe virtual int IndexOf(String source, char value, int startIndex, int count, CompareOptions options)&#123;    // Validate inputs    if (source == null)        throw new ArgumentNullException(&quot;source&quot;);    if (startIndex &lt; 0 || startIndex &gt; source.Length)        throw new ArgumentOutOfRangeException(&quot;startIndex&quot;, Environment.GetResourceString(&quot;ArgumentOutOfRange_Index&quot;));    if (count &lt; 0 || startIndex &gt; source.Length - count)        throw new ArgumentOutOfRangeException(&quot;count&quot;, Environment.GetResourceString(&quot;ArgumentOutOfRange_Count&quot;));    Contract.EndContractBlock();    if (options == CompareOptions.OrdinalIgnoreCase)    &#123;        //         return source.IndexOf(value.ToString(), startIndex, count, StringComparison.OrdinalIgnoreCase);    &#125;    // Validate CompareOptions    // Ordinal can&#x27;t be selected with other flags    if ((options &amp; ValidIndexMaskOffFlags) != 0 &amp;&amp; (options != CompareOptions.Ordinal))        throw new ArgumentException(Environment.GetResourceString(&quot;Argument_InvalidFlag&quot;), &quot;options&quot;);    // to let the sorting DLL do the call optimization in case of Ascii strings, we check if the strings are in Ascii and then send the flag RESERVED_FIND_ASCII_STRING  to     // the sorting DLL API SortFindString so sorting DLL don&#x27;t have to check if the string is Ascii with every call to SortFindString.    return InternalFindNLSStringEx(                m_dataHandle, m_handleOrigin, m_sortName,                 GetNativeCompareFlags(options) | Win32Native.FIND_FROMSTART | ((source.IsAscii() &amp;&amp; (value &lt;= &#x27;\x007f&#x27;)) ? RESERVED_FIND_ASCII_STRING : 0),                source, count, startIndex, new String(value, 1), 1);&#125; // InternalFindNLSStringEx parameters is not exactly matching kernel32::FindNLSStringEx parameters.// Call through to NewApis::FindNLSStringEx so we can get the right behavior[System.Security.SecurityCritical]  // auto-generated[ResourceExposure(ResourceScope.None)][DllImport(JitHelpers.QCall, CharSet = CharSet.Unicode)][SuppressUnmanagedCodeSecurity]private static extern int InternalFindNLSStringEx(IntPtr handle, IntPtr handleOrigin, String localeName, int flags, String source, int sourceCount, int startIndex, string target, int targetCount);

可以看到，最终是调用了  InternalFindNLSStringEx。
不同的选项被转换成了不同的 flag
[Pure]internal static int GetNativeCompareFlags(CompareOptions options)&#123;    // some NLS VM functions can handle COMPARE_OPTIONS_ORDINAL    // in which case options should be simply cast to int instead of using this function    // Does not look like the best approach to me but for now I am going to leave it as it is    //     Contract.Assert(options != CompareOptions.OrdinalIgnoreCase, &quot;[CompareInfo.GetNativeCompareFlags]CompareOptions.OrdinalIgnoreCase should be handled separately&quot;);    // Use &quot;linguistic casing&quot; by default (load the culture&#x27;s casing exception tables)    int nativeCompareFlags = NORM_LINGUISTIC_CASING;    if ((options &amp; CompareOptions.IgnoreCase)       != 0) &#123; nativeCompareFlags |= NORM_IGNORECASE;        &#125;    if ((options &amp; CompareOptions.IgnoreKanaType)   != 0) &#123; nativeCompareFlags |= NORM_IGNOREKANATYPE;    &#125;    if ((options &amp; CompareOptions.IgnoreNonSpace)   != 0) &#123; nativeCompareFlags |= NORM_IGNORENONSPACE;    &#125;    if ((options &amp; CompareOptions.IgnoreSymbols)    != 0) &#123; nativeCompareFlags |= NORM_IGNORESYMBOLS;     &#125;    if ((options &amp; CompareOptions.IgnoreWidth)      != 0) &#123; nativeCompareFlags |= NORM_IGNOREWIDTH;       &#125;    if ((options &amp; CompareOptions.StringSort)       != 0) &#123; nativeCompareFlags |= SORT_STRINGSORT;        &#125;    // Suffix &amp; Prefix shouldn&#x27;t use this, make sure to turn off the NORM_LINGUISTIC_CASING flag    if (options == CompareOptions.Ordinal)                &#123; nativeCompareFlags = COMPARE_OPTIONS_ORDINAL; &#125;    Contract.Assert(((options &amp; ~(CompareOptions.IgnoreCase |                                  CompareOptions.IgnoreKanaType |                                  CompareOptions.IgnoreNonSpace |                                  CompareOptions.IgnoreSymbols |                                  CompareOptions.IgnoreWidth |                                  CompareOptions.StringSort)) == 0) ||                     (options == CompareOptions.Ordinal), &quot;[CompareInfo.GetNativeCompareFlags]Expected all flags to be handled&quot;);    Contract.Assert((nativeCompareFlags &amp; RESERVED_FIND_ASCII_STRING) == 0, &quot;[CompareInfo.GetNativeCompareFlags] RESERVED_FIND_ASCII_STRING shouldn&#x27;t be set here&quot;);    return nativeCompareFlags;&#125;

可以看到继续前进涉及到了 CLR 层的 comnlsinfo
