Span&lt;Char&gt;.IndexOfSystem.Span&lt;T&gt; 是在 .NET 中发挥关键作用的新值类型。使用它，可以表示任意内存的相邻区域，无论相应内存是与托管对象相关联，还是通过互操作由本机代码提供，亦或是位于堆栈上。除了具有上述用途外，它仍能确保安全访问和高性能特性，就像数组一样。官方在 System.Memory.dll 中提供了 MemoryExtensions.IndexOf 方法，同样可以用于字符串的查找。
简单看一下源码MemoryExtensions.Globalization.cs
/// &lt;summary&gt;/// Reports the zero-based index of the first occurrence of the specified &lt;paramref name=&quot;value&quot;/&gt; in the current &lt;paramref name=&quot;span&quot;/&gt;./// &lt;param name=&quot;span&quot;&gt;The source span.&lt;/param&gt;/// &lt;param name=&quot;value&quot;&gt;The value to seek within the source span.&lt;/param&gt;/// &lt;param name=&quot;comparisonType&quot;&gt;One of the enumeration values that determines how the &lt;paramref name=&quot;span&quot;/&gt; and &lt;paramref name=&quot;value&quot;/&gt; are compared.&lt;/param&gt;/// &lt;/summary&gt;public static int IndexOf(this ReadOnlySpan&lt;char&gt; span, ReadOnlySpan&lt;char&gt; value, StringComparison comparisonType)&#123;    string.CheckStringComparison(comparisonType);    if (comparisonType == StringComparison.Ordinal)    &#123;        return SpanHelpers.IndexOf(            ref MemoryMarshal.GetReference(span),            span.Length,            ref MemoryMarshal.GetReference(value),            value.Length);    &#125;    switch (comparisonType)    &#123;        case StringComparison.CurrentCulture:        case StringComparison.CurrentCultureIgnoreCase:            return CultureInfo.CurrentCulture.CompareInfo.IndexOf(span, value, string.GetCaseCompareOfComparisonCulture(comparisonType));        case StringComparison.InvariantCulture:        case StringComparison.InvariantCultureIgnoreCase:            return CompareInfo.Invariant.IndexOf(span, value, string.GetCaseCompareOfComparisonCulture(comparisonType));        default:            Debug.Assert(comparisonType == StringComparison.OrdinalIgnoreCase);            return CompareInfo.IndexOfOrdinalIgnoreCase(span, value, fromBeginning: true);    &#125;&#125;
可以看到，只有 StringComparison.Ordinal 下，调用了 SpanHelpers.IndexOf 方法，其余参数下依旧采用了和 string.IndexOf 一致的 CompareInfo 处理。SpanHelpers.IndexOf
public static int IndexOf(ref byte searchSpace, int searchSpaceLength, ref byte value, int valueLength)&#123;    Debug.Assert(searchSpaceLength &gt;= 0);    Debug.Assert(valueLength &gt;= 0);    if (valueLength == 0)        return 0;  // A zero-length sequence is always treated as &quot;found&quot; at the start of the search space.    byte valueHead = value;    ref byte valueTail = ref Unsafe.Add(ref value, 1);    int valueTailLength = valueLength - 1;    int remainingSearchSpaceLength = searchSpaceLength - valueTailLength;    int offset = 0;    while (remainingSearchSpaceLength &gt; 0)    &#123;        // Do a quick search for the first element of &quot;value&quot;.        int relativeIndex = IndexOf(ref Unsafe.Add(ref searchSpace, offset), valueHead, remainingSearchSpaceLength);        if (relativeIndex == -1)            break;        remainingSearchSpaceLength -= relativeIndex;        offset += relativeIndex;        if (remainingSearchSpaceLength &lt;= 0)            break;  // The unsearched portion is now shorter than the sequence we&#x27;re looking for. So it can&#x27;t be there.        // Found the first element of &quot;value&quot;. See if the tail matches.        if (SequenceEqual(ref Unsafe.Add(ref searchSpace, offset + 1), ref valueTail, (nuint)valueTailLength))  // The (nunit)-cast is necessary to pick the correct overload            return offset;  // The tail matched. Return a successful find.        remainingSearchSpaceLength--;        offset++;    &#125;    return -1;&#125;

