这里直接上 C# 版本源码实现
public static int BoyerMooreIndexOf(this string source, string pattern, int offset = 0, int count = -1) =&gt; BoyerMooreIndexOf(Encoding.UTF8.GetBytes(source), Encoding.UTF8.GetBytes(pattern), offset, count);public static int BoyerMooreIndexOf(this byte[] source, byte[] pattern, int offset = 0, int count = -1)&#123;    if (source == null) throw new ArgumentNullException(nameof(source));    if (pattern == null) throw new ArgumentNullException(nameof(pattern));    var total = source.Length;    var length = pattern.Length;    if (count &gt; 0 &amp;&amp; total &gt; offset + count) total = offset + count;    if (total == 0 || length == 0 || length &gt; total) return -1;    // 初始化坏字符，即不匹配字符    var bads = new int[256];    for (var i = 0; i &lt; 256; i++)        bads[i] = length;    var last = length - 1;    for (var i = 0; i &lt; last; i++)        bads[pattern[i]] = last - i;    var index = offset;    while (index &lt;= total - length)    &#123;        // 尾部开始比较        for (var i = last; source[index + i] == pattern[i]; i--)            if (i == 0) return index;        // 坏字符规则：后移位数 = 坏字符的位置 - 搜索词中的上一次出现位置        index += bads[source[index + last]];    &#125;    return -1;&#125;

KMP截图来自维基百科词条：KMP算法同样直接上源码:
 public static int KMPSearch(this string text, string pattern)&#123;    var n = text.Length;    var m = pattern.Length;    if (n &lt; m) return -1;    if (n == m &amp;&amp; text == pattern) return 0;    if (m == 0) return 0;    var lpsArray = new int[m];    LongestPrefixSuffix(pattern, ref lpsArray);    int i = 0, j = 0;    while (i &lt; n)    &#123;        if (text[i] == pattern[j])        &#123;            i++;            j++;        &#125;        if (j == m)            return i - j;        if (i &gt;= n || text[i] == pattern[j]) continue;        if (j != 0)            j = lpsArray[j - 1];        else            i++;    &#125;    return -1;&#125;public static void LongestPrefixSuffix(string pattern, ref int[] lpsArray)&#123;    var m = pattern.Length;    var len = 0;    lpsArray[0] = 0;    var i = 1;    while (i &lt; m)    &#123;        if (pattern[i] == pattern[len])            lpsArray[i++] = ++len;        else if (len == 0)            lpsArray[i++] = 0;        else            len = lpsArray[len - 1];    &#125;&#125;

