using BenchmarkDotNet.Attributes;using BenchmarkDotNet.Running;using System;using System.Collections.Generic;using System.Text;namespace BenchmarkSample&#123;    public static class Program    &#123;        [RPlotExporter]        public class IndexOfTest        &#123;            private string _haystack;            private string _needle = &quot;needle&quot;;            [Params(100, 10000, 1000000, 100000000)]            public int HaystackSize &#123; get; set; &#125;            [Params(SubstringLocationEnum.Start, SubstringLocationEnum.Middle, SubstringLocationEnum.End,                SubstringLocationEnum.Random)]            public SubstringLocationEnum Location &#123; get; set; &#125;            public IndexOfTest()            &#123;                _haystack = GetRandomString(HaystackSize, _needle, Location); ;            &#125;            [Benchmark]            public int IndexOf() =&gt; _haystack.IndexOf(_needle);            [Benchmark]            public int IndexOfOrdinal() =&gt; _haystack.IndexOf(_needle, StringComparison.Ordinal);            [Benchmark]            public int SpanIndexOf() =&gt; _haystack.AsSpan().IndexOf(_needle);            [Benchmark]            public int SpanIndexOfOrdinal() =&gt; _haystack.AsSpan().IndexOf(_needle, StringComparison.Ordinal);            [Benchmark]            public int BoyerMooreIndexOf() =&gt; _haystack.BoyerMooreIndexOf(_needle);            [Benchmark]            public int KMPIndexOf() =&gt; _haystack.KMPSearch(_needle);        &#125;        public enum SubstringLocationEnum        &#123;            Start = 0, Middle, End, Random        &#125;        /// &lt;summary&gt;        /// 生成随机字符串并加入自定义串        /// &lt;/summary&gt;        /// &lt;param name=&quot;length&quot;&gt;目标字符串的长度&lt;/param&gt;        /// &lt;param name=&quot;custom&quot;&gt;要插入的自定义串&lt;/param&gt;        /// &lt;param name=&quot;location&quot;&gt;插入的位置 0：开头 1：中间 2：尾部 3：随机&lt;/param&gt;        /// &lt;returns&gt;&lt;/returns&gt;        public static string GetRandomString(int length, string custom, SubstringLocationEnum location = SubstringLocationEnum.Middle)        =&gt; GetRandomString(length, true, true, true, true, null, custom, (int)location);        /// &lt;summary&gt;        /// 生成随机字符串         /// &lt;/summary&gt;        /// &lt;param name=&quot;length&quot;&gt;目标字符串的长度&lt;/param&gt;        /// &lt;param name=&quot;useNum&quot;&gt;是否包含数字，1=包含，默认为包含&lt;/param&gt;        /// &lt;param name=&quot;useLow&quot;&gt;是否包含小写字母，1=包含，默认为包含&lt;/param&gt;        /// &lt;param name=&quot;useUpp&quot;&gt;是否包含大写字母，1=包含，默认为包含&lt;/param&gt;        /// &lt;param name=&quot;useSpe&quot;&gt;是否包含特殊字符，1=包含，默认为不包含&lt;/param&gt;        /// &lt;param name=&quot;customChars&quot;&gt;要包含的自定义字符，直接输入要包含的字符列表&lt;/param&gt;        /// &lt;param name=&quot;custom&quot;&gt;要插入的自定义串&lt;/param&gt;        /// &lt;param name=&quot;location&quot;&gt;插入的位置 0：开头 1：中间 2：尾部 3：随机&lt;/param&gt;        /// &lt;returns&gt;指定长度的随机字符串&lt;/returns&gt;        public static string GetRandomString(int length, bool useNum = true, bool useLow = true, bool useUpp = true, bool useSpe = true, string customChars = null, string custom = null, int location = 0)        &#123;            var b = new byte[4];            new System.Security.Cryptography.RNGCryptoServiceProvider().GetBytes(b);            Random r = new(BitConverter.ToInt32(b, 0));            var charList = new List&lt;char&gt;();            var sb = new StringBuilder();            custom ??= string.Empty;            charList.AddRange(custom);            if (useNum) charList.AddRange(&quot;0123456789&quot;);            if (useLow) charList.AddRange(&quot;abcdefghijklmnopqrstuvwxyz&quot;);            if (useUpp) charList.AddRange(&quot;ABCDEFGHIJKLMNOPQRSTUVWXYZ&quot;);            if (useSpe) charList.AddRange(&quot;!\&quot;#$%&amp;&#x27;()*+,-./:;&lt;=&gt;?@[\\]^_`&#123;|&#125;~&quot;);            var charArray = charList.ToArray();            for (var i = 0; i &lt; length; i++)            &#123;                sb.Append(charArray[r.Next(0, charArray.Length - 1)]);            &#125;            var insertIndex = location switch            &#123;                0 =&gt; 0,                1 =&gt; length / 2,                2 =&gt; length - 1,                3 =&gt; r.Next(0, length),                _ =&gt; -1            &#125;;            return sb.Insert(insertIndex, custom).ToString();        &#125;        public static int BoyerMooreIndexOf(this string source, string pattern, int offset = 0, int count = -1) =&gt; BoyerMooreIndexOf(Encoding.UTF8.GetBytes(source), Encoding.UTF8.GetBytes(pattern), offset, count);        /// &lt;summary&gt;Boyer Moore 字符串搜索算法，比KMP更快，常用于IDE工具的查找&lt;/summary&gt;        /// &lt;param name=&quot;source&quot;&gt;&lt;/param&gt;        /// &lt;param name=&quot;pattern&quot;&gt;&lt;/param&gt;        /// &lt;param name=&quot;offset&quot;&gt;&lt;/param&gt;        /// &lt;param name=&quot;count&quot;&gt;&lt;/param&gt;        /// &lt;returns&gt;&lt;/returns&gt;        public static int BoyerMooreIndexOf(this byte[] source, byte[] pattern, int offset = 0, int count = -1)        &#123;            if (source == null) throw new ArgumentNullException(nameof(source));            if (pattern == null) throw new ArgumentNullException(nameof(pattern));            var total = source.Length;            var length = pattern.Length;            if (count &gt; 0 &amp;&amp; total &gt; offset + count) total = offset + count;            if (total == 0 || length == 0 || length &gt; total) return -1;            // 初始化坏字符，即不匹配字符            var bads = new int[256];            for (var i = 0; i &lt; 256; i++)                bads[i] = length;            var last = length - 1;            for (var i = 0; i &lt; last; i++)                bads[pattern[i]] = last - i;            var index = offset;            while (index &lt;= total - length)            &#123;                // 尾部开始比较                for (var i = last; source[index + i] == pattern[i]; i--)                    if