百度语音，面向广大开发者永久免费开放语音合成技术。所采用的离在线融合技术，根据当前网络状况，自动判断使用本地引擎或者云端引擎，进行语音合成，再也不用担心流量消耗了！

本Demo将使用官方提供的C#版本RestApi SDK制作一个Winfrom软件，实现以下两个功能。

TTS语音合成：可选择语速、音调、音量及发言人
ASR语音识别：使用NAudio进行语音录制并识别



Prepare在正式使用之前，我们需要在百度语音获取API key以及SDK文件。
获取API Key在百度语音应用管理页面创建新应用。按照创建引导一步步来即可，注意在选择服务时同时勾选语音识别和语音合成，这样API Key就可以同时用于TTS和ASR了。
下载离线SDK下载C#版本的RestApi SDK。
Coding使用Nuget安装Newtonsoft.Json和NAudio、手动引用官方提供的ApiSdk.dll文件。
接下来查看官方Demo中有关语音的SpeechDemo.cs文件
using System;using System.Collections.Generic;using System.IO;using Baidu.Aip.Speech;namespace Baidu.Aip.Demo&#123;    class SpeechDemo    &#123;        private readonly Asr _asrClient;        private readonly Tts _ttsClient;        public SpeechDemo()        &#123;            _asrClient = new Asr(&quot;Api Key&quot;, &quot;Secret Key&quot;);            _ttsClient = new Tts(&quot;Api Key&quot;, &quot;Secret Key&quot;);        &#125;        // 识别本地文件        public void AsrData()        &#123;            var data = File.ReadAllBytes(&quot;语音pcm文件地址&quot;);            var result = _asrClient.Recognize(data, &quot;pcm&quot;, 16000);            Console.Write(result);        &#125;        // 识别URL中的语音文件        public void AsrUrl()        &#123;            var result = _asrClient.Recoginze(                &quot;http://xxx.com/待识别的pcm文件地址&quot;,                 &quot;http://xxx.com/识别结果回调地址&quot;,                 &quot;pcm&quot;,                 16000);            Console.WriteLine(result);        &#125;        // 合成        public void Tts()        &#123;            // 可选参数            var option = new Dictionary&lt;string, object&gt;()            &#123;                &#123;&quot;spd&quot;, 5&#125;, // 语速                &#123;&quot;vol&quot;, 7&#125;, // 音量                &#123;&quot;per&quot;, 4&#125;  // 发音人，4：情感度丫丫童声            &#125;;            var result = _ttsClient.Synthesis(&quot;众里寻他千百度&quot;, option);            if (result.ErrorCode == 0)  // 或 result.Success            &#123;                File.WriteAllBytes(&quot;合成的语音文件本地存储地址.mp3&quot;, result.Data);            &#125;        &#125;    &#125;&#125;
从代码示例中，我们可以看出语音识别API需要的源语音文件为pcm格式，我们使用NAudio来获取麦克风数据并保存为pcm格式以使用API，同样的也使用NAudio实时预览录制的数据和播放TTS合成的数据。
将官方Demo封装成SpeechHelperusing System.Collections.Generic;using System.IO;using Baidu.Aip.Speech;namespace BaiduSpeechDemo&#123;    static class SpeechHelper    &#123;        private static readonly Asr AsrClient;        private static readonly Tts TtsClient;        static SpeechHelper()        &#123;            AsrClient = new Asr(&quot;BWf8AWrvS5h6Y45NAOP3zaGp&quot;, &quot;490737eca7a6ff4d20375d1696c7e548&quot;);            TtsClient = new Tts(&quot;BWf8AWrvS5h6Y45NAOP3zaGp&quot;, &quot;490737eca7a6ff4d20375d1696c7e548&quot;);        &#125;        // 识别本地文件        public static AsrResult AsrData(string path)        &#123;            var data = File.ReadAllBytes(path);            var result = AsrClient.Recognize(data, &quot;pcm&quot;, 8000);            return result.ToObject&lt;AsrResult&gt;();        &#125;        // 识别URL中的语音文件        public static AsrResult AsrUrl(string url, string callback = &quot;&quot;)        &#123;            var result = AsrClient.Recoginze(                url,                callback,                &quot;pcm&quot;,                16000);            return result.ToObject&lt;AsrResult&gt;();        &#125;        // 合成        public static bool Tts(string input, string path, int spd = 5, int pit = 5, int vol = 6, int per = 4)        &#123;            // 可选参数            var option = new Dictionary&lt;string, object&gt;            &#123;                &#123;&quot;spd&quot;, spd&#125;, // 语速，取值0-9，默认为5中语速                &#123;&quot;pit&quot;, pit&#125;, // 音调，取值0-9，默认为5中语调                &#123;&quot;vol&quot;, vol&#125;, // 音量，取值0-15，默认为5中音量                &#123;&quot;per&quot;, per&#125;  // 发音人选择, 0为普通女声，1为普通男生，3为情感合成-度逍遥，4为情感合成-度丫丫，默认为普通女声            &#125;;            var result = TtsClient.Synthesis(input, option);            if (result.Success) File.WriteAllBytes(path, result.Data);            //Console.WriteLine(result.Serialize());            return result.Success;        &#125;    &#125;&#125;

NAudio录制麦克风数据为pcm格式并实时预览NAudio提供了同时进行录制和播放的Demo，其中的SavingWaveProvider可以直接拿来使用，只要传入合适的参数即可将保存文件的格式由示例中的wav改为pcm，下面是修改后的调用代码。具体则是修改WaveIn的声明：
// 设置记录器// WaveFormat.CreateCustomFormat 参数依次为 格式\采样率\声道\每秒平均码率\单位采样点的字节数\采样位数_recorder = new WaveIn &#123; WaveFormat = WaveFormat.CreateCustomFormat(WaveFormatEncoding.Pcm, 8000, 1, 16000, 2, 16) &#125;;
下面给出修改后的开始录制和结束录制的代码
private WaveIn _recorder;private BufferedWaveProvider _bufferedWaveProvider;private SavingWaveProvider _savingWaveProvider;private WaveOut _player;private void OnStartRecordingClick(object sender, EventArgs e)&#123;    // 设置记录器    // 参数依次为 格式\采样率\声道\每秒平均码率\单位采样点的字节数\采样位数    _recorder = new WaveIn &#123; WaveFormat = WaveFormat.CreateCustomFormat(WaveFormatEncoding.Pcm, 8000, 1, 16000, 2, 16) &#125;;    _recorder.DataAvailable += RecorderOnDataAvailable;    // 建立我们的信号链    _bufferedWaveProvider = new BufferedWaveProvider(_recorder.WaveFormat);    _fileName = Path.Combine(&quot;temp&quot;, Guid.NewGuid() + &quot;.pcm&quot;);    _savingWaveProvider = new SavingWaveProvider(_bufferedWaveProvider, _fileName);    //设置播放    _player = new WaveOut();    _player.Init(_savingWaveProvider);    // 开始播放和录制    _player.Play();    _recorder.StartRecording();&#125;private void RecorderOnDataAvailable(object sender, WaveInEventArgs waveInEventArgs)&#123;    _bufferedWaveProvider.AddSamples(waveInEventArgs.Buffer, 0, waveInEventArgs.BytesRecorded);&#125;private void OnStopRecordingClick(object sender, EventArgs e)&#123;    // 停止录制    _recorder.StopRecording();    // 停止播放    _player.Stop();    // 最终完成 WAV 文件    _savingWaveProvider.Dispose();        // 请求百度ASR API    var a = SpeechHelper.AsrData(_fileName);&#125;
TTS完成窗体界面拖好TTS选项的布局完成按钮点击事件的逻辑
private void btnTts_Click(object sender, EventArgs e)&#123;    // 临时保存路径    var musicPath = Path.Combine(&quot;temp&quot;, Guid.NewGuid() + &quot;.mp3&quot;);    // 发言人    var per = cbPer.SelectedIndex &gt;= 2 ? cbPer.SelectedIndex + 1 : cbPer.SelectedIndex;    //调用Baidu TTS Api    if (!SpeechHelper.Tts(tbContext.Text, musicPath, (int)nudSpd.Value, (int)nudPit.Value, (int)nudVol.Value, per)) return;    //播放请求得到的结果    IWavePlayer waveOutDevice = new WaveOut();    var audioFileReader = new AudioFileReader(musicPath);    waveOutDevice.Init(audioFileReader);    waveOutDevice.Play();    //播放结束后销毁播放对象    waveOutDevice.PlaybackStopped += delegate    &#123;        waveOutDevice?.Stop();        waveOutDevice?.Dispose();        waveOutDevice = null;    &#125;;&#125;
